let timeoffset = 2 * 60 * 60 * 1000;

function sortedStr(str, i) {	
 	  let obj = {};
    let arr = String(str).split('&');
    arr.forEach(item => {
        let [key, value] = item.split('=');
        obj[key] = value;
      });
     var result = Object.keys(obj).sort();
    if(/platform=0/.test(str)){
     result = result
     .map(key=>key + "=" + obj[key]).join("&");
    }else{
     	result = result
     	.map(key=> obj[key]).join("");
    }    
      return result
}

function Token() {	
 	  const { java, source } = this;
    let origin = "https://t.shuqi.com";  	 
   	var token = java.get(origin,{}).cookies()
    .toString().match(/shuqi_token=([^,]*)/)[1];
    var head = {
    		"authorization": "Bearer "+token
    	}; 	
    token = source.putLoginHeader(
    	JSON.stringify(head));
      return token
}

function GetUrl(path, params, sourceUrl) {
 	  const { java, source } = this;
 	  let sourceUrl = sourceUrl || "https://ocean.shuqireader.com";
    var v = source.getVariable();
    try{
    var userId = JSON.parse(v)[0].uid[0].userId;
  }catch(e){
  	  var userId = '8000000';
  	}

    var t = Date.now();
    var time = ~~(t / 1e3);

    var gateway = "sq_h5_gateway";
    var params0 = "sqSv=1.0";
   	 var params1 = `user_id=${userId}&timestamp=${time}`;



   	 if (/info/.test(path)) {
   	  var skey = "37e81a9d8f02596e1b895d07c171d5c9";
   	  var params = params1 + "&" + params;	  
   	  var sign = java.md5Encode(sortedStr(params) + skey);    
     var body = params + "&platform=0&needFreeStack=1&sign=" + sign;

   	}else{
    		var skey = "eefc4798f28ea41622487ad80ef7e81c";
    		var params = params0 + "&" + params1 + "&platform=0&" + params;
   	  var sign = java.md5Encode(sortedStr(params) + "&skey=" + skey );
   	 var body = params + "&key=" + gateway + "&sign=" + sign;

   		}

   if (source.getLoginHeaderMap() == null) {
   	    	this.Token();
   }

   var url = sourceUrl + path + "," + JSON.stringify({
  "body": body,
  "method": "POST"
});

   return url;
}

// SQ_COMMENT_API_V1_BEGIN
var SQ_COMMENT_API_BASE = "https://sq.vv9v.cn";
var _sqRenderExtKey = "";
var _sqRenderExtValue = null;
var _sqMetaMapCache = null;
var _sqShortMapCache = null;

function sqSource() {
    try { if (this && this.source) return this.source; } catch(e) {}
    try { if (typeof source !== "undefined") return source; } catch(e2) {}
    return null;
}

function sqJava() {
    try { if (this && this.java) return this.java; } catch(e) {}
    try { if (typeof java !== "undefined") return java; } catch(e2) {}
    return null;
}

function sqLoginValue(key, defaultValue) {
    try {
        var s = sqSource.call(this);
        var map = s && s.getLoginInfoMap ? s.getLoginInfoMap() : null;
        var value = map && (map.get ? map.get(key) : map[key]);
        if (value !== null && value !== undefined && String(value).trim() !== "") return String(value);
    } catch(e) {}
    return defaultValue == null ? "" : String(defaultValue);
}

function sqToggle(key, defaultValue) {
    var value = sqLoginValue.call(this, key, "");
    if (!value) return !!defaultValue;
    value = String(value).trim().toLowerCase();
    return value === "✅" || value === "1" || value === "true" || value === "开" || value === "开启";
}

function sqCommentConfig() {
    var style = sqLoginValue.call(this, "◎ 模板", "起点");
    var templateKey = String(style).replace("样式", "◎ 气泡");
    return {
        paragraph: sqToggle.call(this, "段评开关", false),
        chapter: sqToggle.call(this, "章评开关", false),
        color: sqLoginValue.call(this, "段评气泡颜色", "#666666"),
        colorSplit: sqToggle.call(this, "段评分色", false),
        splitColor: sqLoginValue.call(this, "分色气泡颜色", "#e23b3b"),
        splitCount: Number(sqLoginValue.call(this, "分色评论数", "45")) || 45,
        hotColor: sqLoginValue.call(this, "热门气泡颜色", "#f06060"),
        theme: sqLoginValue.call(this, "评论主题", "自动"),
        height: sqLoginValue.call(this, "评论窗口高度", "80"),
        bubbleStyle: style,
        bubbleSize: sqLoginValue.call(this, "◎ 大小", "text"),
        bubbleTemplate: sqLoginValue.call(this, templateKey, "")
    };
}

function sqApiKey() {
    return sqLoginValue.call(this, "书旗apikey", "") || sqLoginValue.call(this, "书旗评论 API Key", "");
}

function sqPost(path, body) {
    var j = sqJava.call(this);
    if (!j) return { ok: false, error: "java unavailable" };
    var apiKey = sqApiKey.call(this);
    if (!apiKey) return { ok: false, error: "请先在登录页填写书旗apikey" };
    var payload = body || {};
    payload.apiKey = apiKey;
    var option = {
        method: "POST",
        body: JSON.stringify(payload),
        headers: { "Content-Type": "application/json", "Accept": "application/json" }
    };
    try {
        var raw = j.ajax(SQ_COMMENT_API_BASE + path + "," + JSON.stringify(option));
        var text = String(raw || "{}").replace(/^\uFEFF/, "").trim();
